function parse_BrtMdtinfo(data, length) {
	return {
		flags: data.read_shift(4),
		version: data.read_shift(4),
		name: parse_XLWideString(data, length - 8)
	};
}
function write_BrtMdtinfo(data) {
	var o = new_buf(12 + 2 * data.name.length);
	o.write_shift(4, data.flags);
	o.write_shift(4, data.version);
	write_XLWideString(data.name, o);
	return o.slice(0, o.l);
}
function parse_BrtMdb(data) {
	var out = [];
	var cnt = data.read_shift(4);
	while (cnt-- > 0) out.push([data.read_shift(4), data.read_shift(4)]);
	return out;
}
function write_BrtMdb(mdb) {
	var o = new_buf(4 + 8 * mdb.length);
	o.write_shift(4, mdb.length);
	for (var i = 0; i < mdb.length; ++i) {
		o.write_shift(4, mdb[i][0]);
		o.write_shift(4, mdb[i][1]);
	}
	return o;
}
function write_BrtBeginEsfmd(cnt, name) {
	var o = new_buf(8 + 2 * name.length);
	o.write_shift(4, cnt);
	write_XLWideString(name, o);
	return o.slice(0, o.l);
}
function parse_BrtBeginEsmdb(data) {
	data.l += 4;
	return data.read_shift(4) != 0;
}
function write_BrtBeginEsmdb(cnt, cm) {
	var o = new_buf(8);
	o.write_shift(4, cnt);
	o.write_shift(4, cm ? 1 : 0);
	return o;
}
function write_xlmeta_bin() {
	var ba = buf_array();
	write_record(ba, 332);
	write_record(ba, 334, write_UInt32LE(1));
	write_record(ba, 335, write_BrtMdtinfo({
		name: "XLDAPR",
		version: 12e4,
		flags: 3496657072
	}));
	write_record(ba, 336);
	write_record(ba, 339, write_BrtBeginEsfmd(1, "XLDAPR"));
	write_record(ba, 52);
	write_record(ba, 35, write_UInt32LE(514));
	write_record(ba, 4096, write_UInt32LE(0));
	write_record(ba, 4097, writeuint16(1));
	write_record(ba, 36);
	write_record(ba, 53);
	write_record(ba, 340);
	write_record(ba, 337, write_BrtBeginEsmdb(1, true));
	write_record(ba, 51, write_BrtMdb([[1, 0]]));
	write_record(ba, 338);
	write_record(ba, 333);
	return ba.end();
}
function write_xlmeta_xml() {
	var o = [XML_HEADER];
	o.push("<metadata xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:xlrd=\"http://schemas.microsoft.com/office/spreadsheetml/2017/richdata\" xmlns:xda=\"http://schemas.microsoft.com/office/spreadsheetml/2017/dynamicarray\">\n  <metadataTypes count=\"1\">\n    <metadataType name=\"XLDAPR\" minSupportedVersion=\"120000\" copy=\"1\" pasteAll=\"1\" pasteValues=\"1\" merge=\"1\" splitFirst=\"1\" rowColShift=\"1\" clearFormats=\"1\" clearComments=\"1\" assign=\"1\" coerce=\"1\" cellMeta=\"1\"/>\n  </metadataTypes>\n  <futureMetadata name=\"XLDAPR\" count=\"1\">\n    <bk>\n      <extLst>\n        <ext uri=\"{bdbb8cdc-fa1e-496e-a857-3c3f30c029c3}\">\n          <xda:dynamicArrayProperties fDynamic=\"1\" fCollapsed=\"0\"/>\n        </ext>\n      </extLst>\n    </bk>\n  </futureMetadata>\n  <cellMetadata count=\"1\">\n    <bk>\n      <rc t=\"1\" v=\"0\"/>\n    </bk>\n  </cellMetadata>\n</metadata>");
	return o.join("");
}
function parse_BrtCalcChainItem$(data) {
	var out = {};
	out.i = data.read_shift(4);
	var cell = {};
	cell.r = data.read_shift(4);
	cell.c = data.read_shift(4);
	out.r = encode_cell(cell);
	var flags = data.read_shift(1);
	if (flags & 2) out.l = "1";
	if (flags & 8) out.a = "1";
	return out;
}
var _shapeid = 1024;
function write_comments_vml(rId, comments) {
	var csize = [21600, 21600];
	var bbox = [
		"m0,0l0",
		csize[1],
		csize[0],
		csize[1],
		csize[0],
		"0xe"
	].join(",");
	var o = [
		writextag("xml", null, {
			"xmlns:v": XLMLNS.v,
			"xmlns:o": XLMLNS.o,
			"xmlns:x": XLMLNS.x,
			"xmlns:mv": XLMLNS.mv
		}).replace(/\/>/, ">"),
		writextag("o:shapelayout", writextag("o:idmap", null, {
			"v:ext": "edit",
			"data": rId
		}), { "v:ext": "edit" }),
		writextag("v:shapetype", [writextag("v:stroke", null, { joinstyle: "miter" }), writextag("v:path", null, {
			gradientshapeok: "t",
			"o:connecttype": "rect"
		})].join(""), {
			id: "_x0000_t202",
			"o:spt": 202,
			coordsize: csize.join(","),
			path: bbox
		})
	];
	while (_shapeid < rId * 1e3) _shapeid += 1e3;
	comments.forEach(function(x) {
		var c = decode_cell(x[0]);
		var fillopts = {
			"color2": "#BEFF82",
			"type": "gradient"
		};
		if (fillopts.type == "gradient") fillopts.angle = "-180";
		var fillxml = writextag("v:fill", fillopts.type == "gradient" ? writextag("o:fill", null, {
			type: "gradientUnscaled",
			"v:ext": "view"
		}) : null, fillopts);
		var shadata = {
			on: "t",
			"obscured": "t"
		};
		++_shapeid;
		o = o.concat([
			"<v:shape" + wxt_helper({
				id: "_x0000_s" + _shapeid,
				type: "#_x0000_t202",
				style: "position:absolute; margin-left:80pt;margin-top:5pt;width:104pt;height:64pt;z-index:10" + (x[1].hidden ? ";visibility:hidden" : ""),
				fillcolor: "#ECFAD4",
				strokecolor: "#edeaa1"
			}) + ">",
			fillxml,
			writextag("v:shadow", null, shadata),
			writextag("v:path", null, { "o:connecttype": "none" }),
			"<v:textbox><div style=\"text-align:left\"></div></v:textbox>",
			"<x:ClientData ObjectType=\"Note\">",
			"<x:MoveWithCells/>",
			"<x:SizeWithCells/>",
			writetag("x:Anchor", [
				c.c + 1,
				0,
				c.r + 1,
				0,
				c.c + 3,
				20,
				c.r + 5,
				20
			].join(",")),
			writetag("x:AutoFill", "False"),
			writetag("x:Row", String(c.r)),
			writetag("x:Column", String(c.c)),
			x[1].hidden ? "" : "<x:Visible/>",
			"</x:ClientData>",
			"</v:shape>"
		]);
	});
	o.push("</xml>");
	return o.join("");
}
function write_comments_xml(data) {
	var o = [XML_HEADER, writextag("comments", null, { "xmlns": XMLNS_main[0] })];
	var iauthor = [];
	o.push("<authors>");
	data.forEach(function(x) {
		x[1].forEach(function(w) {
			var a = escapexml(w.a);
			if (iauthor.indexOf(a) == -1) {
				iauthor.push(a);
				o.push("<author>" + a + "</author>");
			}
			if (w.T && w.ID && iauthor.indexOf("tc=" + w.ID) == -1) {
				iauthor.push("tc=" + w.ID);
				o.push("<author>tc=" + w.ID + "</author>");
			}
		});
	});
	if (iauthor.length == 0) {
		iauthor.push("SheetJ5");
		o.push("<author>SheetJ5</author>");
	}
	o.push("</authors>");
	o.push("<commentList>");
	data.forEach(function(d) {
		var lastauthor = 0, ts = [];
		if (d[1][0] && d[1][0].T && d[1][0].ID) lastauthor = iauthor.indexOf("tc=" + d[1][0].ID);
		else d[1].forEach(function(c) {
			if (c.a) lastauthor = iauthor.indexOf(escapexml(c.a));
			ts.push(c.t || "");
		});
		o.push("<comment ref=\"" + d[0] + "\" authorId=\"" + lastauthor + "\"><text>");
		if (ts.length <= 1) o.push(writetag("t", escapexml(ts[0] || "")));
		else {
			var t = "Comment:\n    " + ts[0] + "\n";
			for (var i = 1; i < ts.length; ++i) t += "Reply:\n    " + ts[i] + "\n";
			o.push(writetag("t", escapexml(t)));
		}
		o.push("</text></comment>");
	});
	o.push("</commentList>");
	if (o.length > 2) {
		o[o.length] = "</comments>";
		o[1] = o[1].replace("/>", ">");
	}
	return o.join("");
}
function write_tcmnt_xml(comments, people, opts) {
	var o = [XML_HEADER, writextag("ThreadedComments", null, { "xmlns": XMLNS.TCMNT }).replace(/[\/]>/, ">")];
	comments.forEach(function(carr) {
		var rootid = "";
		(carr[1] || []).forEach(function(c, idx) {
			if (!c.T) {
				delete c.ID;
				return;
			}
			if (c.a && people.indexOf(c.a) == -1) people.push(c.a);
			var tcopts = {
				ref: carr[0],
				id: "{54EE7951-7262-4200-6969-" + ("000000000000" + opts.tcid++).slice(-12) + "}"
			};
			if (idx == 0) rootid = tcopts.id;
			else tcopts.parentId = rootid;
			c.ID = tcopts.id;
			if (c.a) tcopts.personId = "{54EE7950-7262-4200-6969-" + ("000000000000" + people.indexOf(c.a)).slice(-12) + "}";
			o.push(writextag("threadedComment", writetag("text", c.t || ""), tcopts));
		});
	});
	o.push("</ThreadedComments>");
	return o.join("");
}
