var parsePhoneNumber = (phone) => {
	if (!phone) return {
		dialCode: "+91",
		localNumber: ""
	};
	const sortedCodes = [...COUNTRY_CODES].sort((a, b) => b.dialCode.length - a.dialCode.length);
	for (const c of sortedCodes) if (phone.startsWith(c.dialCode)) return {
		dialCode: c.dialCode,
		localNumber: phone.substring(c.dialCode.length)
	};
	if (phone.startsWith("+")) {
		const match = phone.match(/^\+(\d+)/);
		if (match) {
			const dial = "+" + match[1];
			return {
				dialCode: dial,
				localNumber: phone.substring(dial.length)
			};
		}
	}
	return {
		dialCode: "+91",
		localNumber: phone
	};
};
