	const refreshCustomerHistory = async (phone) => {
		if (!phone) return;
		try {
			setCustomerHistoryData((await posService.getCustomerHistory(phone)).data || {
				orders: [],
				transactions: []
			});
		} catch (err) {
			console.error("Failed to refresh customer history:", err);
		}
	};
	const updateOrderPrinterSetting = (orderTypeKey, jobType, field, value) => {
		setPosSettings((prev) => {
			const printers = { ...prev.orderPrinters || {} };
			if (!printers[orderTypeKey]) printers[orderTypeKey] = {
				kot: {
					enabled: true,
					name: "",
					paperSize: "THERMAL_80MM"
				},
				bill: {
					enabled: true,
					name: "",
					paperSize: "THERMAL_80MM"
				}
			};
			printers[orderTypeKey] = {
				...printers[orderTypeKey],
				[jobType]: {
					...printers[orderTypeKey][jobType] || {},
					[field]: value
				}
			};
			return {
				...prev,
				orderPrinters: printers
			};
		});
	};
	const compileLedgerData = () => {
		const ledger = [];
		if (Array.isArray(customerHistoryData.orders)) customerHistoryData.orders.forEach((order) => {
			if (order.status === "CANCELLED") return;
			const grandTotal = getReceiptGrandTotal(order, posSettings?.isTaxInclusive);
			const paid = parseFloat(order.paid_amount || 0);
			let parsedItems = [];
			try {
				parsedItems = typeof order.items === "string" ? JSON.parse(order.items) : order.items;
				if (!Array.isArray(parsedItems)) parsedItems = [];
			} catch (e) {
				parsedItems = [];
			}
			ledger.push({
				date: new Date(order.created_at),
				type: "ORDER",
				reference: `#${order.bill_no || order.id}`,
				description: `Bill #${order.bill_no || order.id} (${order.payment_method})`,
				debit: grandTotal,
				credit: paid,
				items: parsedItems,
				rawRecord: order
			});
		});
		if (Array.isArray(customerHistoryData.transactions)) customerHistoryData.transactions.forEach((tx) => {
			if ([
				"CREDIT_PURCHASE",
				"CREDIT_REFUND",
				"BILL_PAYMENT_REVERSAL"
			].includes(tx.type)) return;
			if (tx.type === "BILL_PAYMENT" && tx.reason && tx.reason.toLowerCase().includes("overpayment")) return;
			const amtVal = parseFloat(tx.amount) || 0;
			let debit = 0;
			let credit = 0;
			if (amtVal > 0) credit = amtVal;
			else if (amtVal < 0) debit = Math.abs(amtVal);
			ledger.push({
				date: new Date(tx.created_at),
				type: "TRANSACTION",
				reference: tx.type,
				description: tx.reason || tx.type.replace("_", " "),
				debit,
				credit,
				items: [],
				rawRecord: tx
			});
		});
		ledger.sort((a, b) => a.date - b.date);
		let currentBalance = 0;
		return ledger.map((entry) => {
			currentBalance = currentBalance + entry.credit - entry.debit;
			return {
				...entry,
				balance: currentBalance
			};
		});
	};
