	const handleImportBackup = () => {
		const fileInput = document.createElement("input");
		fileInput.type = "file";
		fileInput.accept = ".json";
		fileInput.onchange = (e) => {
			const file = e.target.files[0];
			if (!file) return;
			const reader = new FileReader();
			reader.onload = (event) => {
				try {
					const data = JSON.parse(event.target.result);
					if (data.posSettings) {
						setPosSettings(data.posSettings);
						localStorage.setItem("pos_settings", JSON.stringify(data.posSettings));
					}
					if (data.tableBills) {
						setTableBills(data.tableBills);
						localStorage.setItem("pos_table_bills", JSON.stringify(data.tableBills));
					}
					if (data.tableCarts) {
						setTableCarts(data.tableCarts);
						localStorage.setItem("pos_table_carts", JSON.stringify(data.tableCarts));
					}
					if (data.tableBillNumbers) {
						setTableBillNumbers(data.tableBillNumbers);
						localStorage.setItem("pos_table_bill_numbers", JSON.stringify(data.tableBillNumbers));
					}
					if (data.tableActiveTimestamps) {
						setTableActiveTimestamps(data.tableActiveTimestamps);
						localStorage.setItem("pos_table_active_timestamps", JSON.stringify(data.tableActiveTimestamps));
					}
					if (data.nextBillNo) {
						setNextBillNo(data.nextBillNo);
						localStorage.setItem("pos_next_bill_no", String(data.nextBillNo));
					}
					if (data.recentOrders) {
						setRecentOrders(data.recentOrders);
						localStorage.setItem("pos_recent_orders", JSON.stringify(data.recentOrders));
					}
					y.success("Backup imported successfully!");
				} catch (err) {
					console.error(err);
					y.error("Invalid backup file.");
				}
			};
			reader.readAsText(file);
		};
		fileInput.click();
	};
